// E3. 较早查询在较晚查询在途时抢先失败，较晚查询随后成功：失败提示从未上屏，
// 页面直接展示较晚查询的新列表。
test('交错：较早查询抢先失败不上屏，较晚查询成功后直接展示新列表', { timeout: 60000 }, async (t) => {
  const { page, baseURL, lists } = await setupGatedPage(t, [SEED_ALPHA, SEED_BETA]);

