  await waitForMessageKind(page, 'ok');
  await waitForRowCount(page, 1);
  const rows = await readRows(page);
  assertRoomRowCells(rows[0], created, {
    gameText: '飞行棋', capText: '4 人', turnText: '10 秒',
  });
